    // DAO Instances
    private UserDao userDao = (UserDao) AppUtil.getApplicationContext().getBean("userDao");
    private EmploymentDao employmentDao = (EmploymentDao) AppUtil.getApplicationContext().getBean("employmentDao");

    // Method to concatenate names with random digits
    public static String concatenateNamesWithRandomDigits(String prenom, String nom) {
        Random random = new Random();
        int randomNumber = random.nextInt(1000); // Generates a random number between 0 and 999
        return prenom + "." + nom + randomNumber;
    }

    // Method to send the registration email
    public void mail() {
        // Form field values
        String id = "#form.inscription_etud.id#";
        String id_unic = "#form.inscription_etud.id_etudiant#";
        String Nom = "#form.inscription_etud.nom#";
        String prenom = "#form.inscription_etud.prenom#";
        String userEmail = concatenateNamesWithRandomDigits(prenom, Nom);
        String Email = "#form.inscription_etud.email#";
        String tel = "#form.inscription_etud.numero_de_telephone#";
        String Validation = "Oui";
        String password = "#form.inscription_etud.nouveau_mdp#";
        
        // Encrypt the password
        String pass = StringUtil.md5Base16(password);
        LogUtil.info("password crypté : ", pass);

        Connection con = null;
        Transport transport = null;

        try {
            // Get DataSource and establish connection
            DataSource ds = (DataSource) AppUtil.getApplicationContext().getBean("setupDataSource");
            con = ds.getConnection();

            String user = "";
            String userident = "";

            if (!con.isClosed()) {
                // Check if user exists
                String sqluser = "SELECT username, id FROM jwdb.dir_user WHERE username = '" + userEmail + "'";
                PreparedStatement stmt1 = con.prepareStatement(sqluser);
                ResultSet rs1 = stmt1.executeQuery();
                LogUtil.info("---------------------------->", sqluser);

                if (rs1.next()) {
                    user = rs1.getString(1);
                    LogUtil.info("------------user---------------->", user);
                    userident = rs1.getString(2);
                    LogUtil.info("------------userident---------------->", userident);
                }

                    // Insert new user into dir_user table
                    String sql1 = 
                        "INSERT INTO jwdb.dir_user (id, username, firstName, lastName, email, password, active) " +
                        "VALUES ('" + userEmail + "', '" + userEmail + "', '" + prenom + "', '" + Nom + "', '" + Email + "', '" + pass + "', 1)";
                    PreparedStatement stmt2 = con.prepareStatement(sql1);
                    stmt2.executeUpdate();
                    LogUtil.info("---------------------------->", sql1);
                    
                    // Insert new user role
                    String sql2 = 
                        "INSERT INTO jwdb.dir_user_role (roleId, userId) " +
                        "SELECT 'ROLE_USER', id FROM jwdb.dir_user WHERE id = '" + userEmail + "'";
                    PreparedStatement stmt3 = con.prepareStatement(sql2);
                    stmt3.executeUpdate();
                    LogUtil.info("---------------------------->", sql2);
                    
                    // Insert new employment record
                    UuidGenerator uuid = UuidGenerator.getInstance();
                    String sql3 = 
                        "INSERT INTO jwdb.dir_employment (id, userId, departmentId, organizationId) " +
                        "VALUES ('" + userEmail + "', '" + userEmail + "', 'etudiants', 'education')";
                    PreparedStatement stmt4 = con.prepareStatement(sql3);
                    stmt4.executeUpdate();
                    LogUtil.info("---------------------------->", sql3);
                    
                    // Update the id in app_fd_inscription_etud
                    String updateQuery = 
                        "UPDATE app_fd_inscription_etud " +
                        "SET id = '" + Email + "' " +
                        "WHERE id = '#form.inscription_etud.id#'";
                    PreparedStatement stmtUpdate = con.prepareStatement(updateQuery);
                    stmtUpdate.executeUpdate();
                    LogUtil.info("---------------------------->", updateQuery);


                
        LogUtil.info("--------------- Assign to grp ------------->",String.valueOf(userDao.assignUserToGroup(userEmail,"first_login")));

                // Send registration confirmation email
                String encodedUserEmail = URLEncoder.encode(userEmail, StandardCharsets.UTF_8.toString());
                String activationUrl = "#envVariable.url#jw/web/userview/appcenter/inscription/_/verification_compte?var_mail_user=" + encodedUserEmail;
                String subject = "MESRS : Activez votre compte";

                String emailContent = "<html><body style='font-family: Arial, sans-serif;'>" +
                        "<p style='font-size: 14px;'>Bonjour,</p>" +
                        "<p style='font-size: 14px;'>Nous sommes ravis de vous informer que votre espace dédié sur notre plateforme de gestion de l'enseignement supérieur privé est désormais accessible. " +
                        "Cependant, votre compte n'est pas encore activé.</p>" +
                        "<p style='font-size: 14px;'>Pour finaliser l'enregistrement, veuillez activer votre compte en cliquant sur le bouton d'activation ci-dessous :</p>" +
                        "<p style='text-align: center;'><a href='" + activationUrl + "' style='background-color: #28a745; color: white; padding: 10px 20px; text-decoration: none; border-radius: 5px;' target='_blank'>" +
                        "Je confirme et je souhaite activer mon compte</a></p>" +
                        "<p style='font-size: 14px;'>Après l'activation, vous pouvez vous connecter en utilisant vos paramètres :</p>" +
                        "<p style='font-size: 14px;'><strong>Nom d'utilisateur :</strong> " + userEmail + "<br>" +
                        "<strong>Mot de passe :</strong> " + password + "</p>" +
                        "<p style='font-size: 14px;'>Votre compte vous donne accès à notre plateforme. Nous vous invitons à bien suivre les consignes dès votre première connexion pour garantir une utilisation optimale.</p>" +
                        "<p style='font-size: 14px; color: red;'><strong>Attention :</strong> Si vous n'activez pas votre compte, il sera automatiquement supprimé ! " +
                        "Dans ce cas, le lien d'activation ci-dessus n'a plus d'effet et les paramètres d'accès ne sont plus valables.</p>" +
                        "<p style='font-size: 12px; color: #888;'>Ce message est envoyé automatiquement. Merci de ne pas y répondre. Si vous avez besoin d'aide, veuillez nous contacter sur info@votreplateforme.com.</p>" +
                        "</body></html>";

                sendMail(subject, userEmail, emailContent);
            }

            // Delete user data if validation is "Non"
            if (Validation.equals("Non") && user != null && !user.trim().isEmpty()) {
                deleteUserData(userEmail, con);
            }

        } catch (Exception e) {
            System.err.println("Exception: " + e.getMessage());
        } finally {
            try {
                if (con != null) {
                    con.close();
                }
            } catch (SQLException e) {
                // Handle exception
            }
        }
    }

    // Method to delete user data
    private void deleteUserData(String userEmail, Connection con) throws SQLException {
        String sql2 = "DELETE FROM jwdb.dir_user_role WHERE roleId = 'ROLE_USER' AND userId = ?";
        PreparedStatement stmt3 = con.prepareStatement(sql2);
        stmt3.setString(1, userEmail);
        stmt3.executeUpdate();
        LogUtil.info("---------------------------->", sql2);

        String deleteSql = "DELETE FROM jwdb.dir_employment WHERE userId = ?";
        PreparedStatement stmtDelete = con.prepareStatement(deleteSql);
        stmtDelete.setString(1, userEmail);
        stmtDelete.executeUpdate();
        LogUtil.info("---------------------------->", deleteSql);

        String deleteSql2 = "DELETE FROM jwdb.dir_user WHERE id = ?";
        PreparedStatement stmtDelete2 = con.prepareStatement(deleteSql2);
        stmtDelete2.setString(1, userEmail);
        stmtDelete2.executeUpdate();
        LogUtil.info("---------------------------->", deleteSql2);
    }

    // Method to send email
    private void sendMail(String subject, String email, String emailContent) {
        Plugin plugin = pluginManager.getPlugin("org.joget.apps.app.lib.EmailTool");
        Map propertiesMap = AppPluginUtil.getDefaultProperties(plugin, null, appDef, null);
        propertiesMap.put("pluginManager", pluginManager);
        propertiesMap.put("appDef", appDef);
        propertiesMap.put("request", request);
        ApplicationPlugin emailTool = (ApplicationPlugin) plugin;

        propertiesMap.put("toSpecific", email);
        propertiesMap.put("subject", subject);
        propertiesMap.put("message", emailContent);

        ((PropertyEditable) emailTool).setProperties(propertiesMap);
        emailTool.execute(propertiesMap);
    }

